from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class RangeValue(SchemaObject):
    default_value = SchemaField(name='default_value')
    min = SchemaField(name='min')
    max = SchemaField(name='max')
    unit = SchemaField(name='unit')
    step = SchemaField(name='step')
    range_desc = SchemaField(name='range_desc')

    def __init__(self, default_value, min, max, unit, step, range_desc):
        self.default_value = default_value
        self.min = min
        self.max = max
        self.unit = unit
        self.step = step
        self.range_desc = range_desc

        super(RangeValue, self).__init__()


class BooleanValue(SchemaObject):
    default_value = SchemaField(name='default_value')
    default_desc = SchemaField(name='default_desc')

    def __init__(self, default_value, default_desc):
        self.default_value = default_value
        self.default_desc = default_desc

        super(BooleanValue, self).__init__()


class EnumValues(SchemaObject):
    value = SchemaField(name='value')
    default_desc = SchemaField(name='default_desc')
    text = SchemaField(name='text')
    performance_impact = SchemaField(name='performance_impact')
    status = SchemaField(name='status')

    def __init__(self, value, default_desc, text, performance_impact, status):
        self.value = value
        self.default_desc = default_desc
        self.text = text
        self.performance_impact = performance_impact
        self.status = status

        super(EnumValues, self).__init__()


class BitmaskValues(SchemaObject):
    value = SchemaField(name='value')
    default_desc = SchemaField(name='default_desc')
    text = SchemaField(name='text')
    performance_impact = SchemaField(name='performance_impact')
    status = SchemaField(name='status')

    def __init__(self, value, default_desc, text, performance_impact, status):
        self.value = value
        self.default_desc = default_desc
        self.text = text
        self.performance_impact = performance_impact
        self.status = status

        super(BitmaskValues, self).__init__()


class Parameters(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    name = SchemaField(name='name', not_null=True)
    description = SchemaField(name='description', not_null=True)
    default_value = SchemaField(name='default_value', not_null=True)
    current_value = SchemaField(name='current_value', not_null=True)
    performance_impact = SchemaField(name='performance_impact')
    hw_restriction = SchemaField(name='hw_restriction')
    type = SchemaField(name='type', not_null=True)
    number_type = SchemaField(name='number_type')
    range_value = SchemaField(name='range_value', klass=RangeValue, optional=True)
    boolean_value = SchemaField(name='boolean_value', klass=BooleanValue, optional=True)
    enum_values = SchemaField(name='enum_values', many=True, klass=EnumValues, optional=True)
    bitmask_values = SchemaField(name='bitmask_values', many=True, klass=BitmaskValues, optional=True)

    def __init__(self, id, name, description, default_value, current_value, performance_impact, hw_restriction, type,
                 number_type, range_value, boolean_value, enum_values, bitmask_values):
        self.id = id
        self.name = name
        self.description = description
        self.default_value = default_value
        self.current_value = current_value
        self.performance_impact = performance_impact
        self.hw_restriction = hw_restriction
        self.type = type
        self.number_type = number_type
        self.range_value = range_value
        self.boolean_value = boolean_value
        self.enum_values = enum_values
        self.bitmask_values = bitmask_values

        super(Parameters, self).__init__()


class RadParams(SchemaObject):
    domain_id = SchemaField(name='domain_id')
    domain_name = SchemaField(name='domain_name')
    parameters = SchemaField(name='parameters', many=True, klass=Parameters)

    def __init__(self, domain_id, domain_name, parameters):
        self.domain_id = domain_id
        self.domain_name = domain_name
        self.parameters = parameters

        super(RadParams, self).__init__()


class RadParamsResponse(SchemaObject):
    operation_id = SchemaField(name='operation_id', not_null=True)
    status = SchemaField(name='status', not_null=True)
    error_message = SchemaField(name='error_message', optional=True)
    rad_params = SchemaField(name='rad_params', many=True, klass=RadParams, optional=True)

    def __init__(self, operation_id, status, error_message, rad_params):
        self.operation_id = operation_id
        self.status = status
        self.error_message = error_message
        self.rad_params = rad_params

        super(RadParamsResponse, self).__init__()
